-- =====================================================================
--  BLOC E - VERIFICATION
--  Attendu : 4 grille(s), 5 sujet(s), 25 etalon(s), 4 gabarit(s),
--  et AUCUN sujet a moins de 3 etalons.
-- =====================================================================

select 'grilles' as objet, count(*) as n from public.rubrics where matiere = 'histoire-geo'
union all select 'sujets', count(*) from public.subject_cards where matiere = 'histoire-geo'
union all select 'etalons', count(*) from public.benchmark_cards b
  join public.subject_cards s on s.id = b.subject_id where s.matiere = 'histoire-geo'
union all select 'gabarits', count(*) from public.dossier_templates where matiere = 'histoire-geo';

select s.id, s.exercise_type, s.status, count(b.id) as etalons
from public.subject_cards s
left join public.benchmark_cards b on b.subject_id = s.id
where s.matiere = 'histoire-geo'
group by s.id, s.exercise_type, s.status
order by s.id;
